export function regtechProgram() {
  return <T extends RegtechPluginRequirements>(
    client: T,
  ): Omit<T, "regtech"> & { regtech: RegtechPlugin } => {
    return extendClient(client, {
      regtech: <RegtechPlugin>{
        accounts: {
          attempt: addSelfFetchFunctions(client, getAttemptCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          credential: addSelfFetchFunctions(client, getCredentialCodec()),
          enrollment: addSelfFetchFunctions(client, getEnrollmentCodec()),
          module: addSelfFetchFunctions(client, getModuleCodec()),
          partner: addSelfFetchFunctions(client, getPartnerCodec()),
        },
        instructions: {
          acceptAdminUpdate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptAdminUpdateInstructionAsync(input),
            ),
          allocateQuizzes: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAllocateQuizzesInstructionAsync(input),
            ),
          claimCredential: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimCredentialInstructionAsync(input),
            ),
          closeAttempt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseAttemptInstruction(input),
            ),
          closeCredential: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseCredentialInstruction(input),
            ),
          enrollUser: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEnrollUserInstructionAsync(input),
            ),
          fundPartner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFundPartnerInstructionAsync(input),
            ),
          initializeConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeConfigInstructionAsync(input),
            ),
          proposeAdminUpdate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeAdminUpdateInstructionAsync(input),
            ),
          refundPartner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRefundPartnerInstructionAsync(input),
            ),
          refundQuizzes: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRefundQuizzesInstructionAsync(input),
            ),
          registerModule: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterModuleInstructionAsync(input),
            ),
          registerPartner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterPartnerInstructionAsync(input),
            ),
          revokeCredential: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeCredentialInstruction(input),
            ),
          revokeEnrollment: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeEnrollmentInstruction(input),
            ),
          rotateAttestor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRotateAttestorInstruction(input),
            ),
          setModuleActive: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetModuleActiveInstruction(input),
            ),
          setPartnerActive: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPartnerActiveInstructionAsync(input),
            ),
          setPaused: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPausedInstructionAsync(input),
            ),
          startAttempt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getStartAttemptInstructionAsync(input),
            ),
          submitAttempt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSubmitAttemptInstructionAsync(input),
            ),
        },
        pdas: { config: findConfigPda, partner: findPartnerPda },
      },
    });
  };
}
